<?php
declare(strict_types=1);
function globalTrialCases(array &$tests,ControlCenter\Application $app,ControlCenter\Config $config,array $owner,HttpFixture $http,string $password):void {
    $service=null;$policies=null;$offers=null;$artifacts=null;$a=null;$b=null;$ta=null;$tb=null;$ba=null;$bb=null;$ownerBrand=null;$catalogCalls=0;$provisions=0;$plans=[];
    $tests['global trial model preserves the existing owner offer and needs no per-reseller admin grant']=function()use($app,$config,$owner,$password,&$service,&$policies,&$offers,&$artifacts,&$a,&$b,&$ta,&$tb,&$ba,&$bb,&$ownerBrand,&$catalogCalls,&$provisions,&$plans):void {
        same(0,(int)$app->db->one('SELECT enabled FROM trial_global_packages WHERE id=1')['enabled']);
        $ownerBrand=$app->db->one("SELECT b.* FROM app_brands b JOIN tenants t ON t.id=b.tenant_id WHERE t.kind='owner'");
        $plans=[['id'=>17,'name'=>'TEST owner trial','duration'=>24,'period'=>'hours','max_connections'=>1,'credits'=>'0','bouquets'=>[10],'fingerprint'=>str_repeat('4',64)],['id'=>71,'name'=>'TEST global 24 hours','duration'=>24,'period'=>'hours','max_connections'=>2,'credits'=>'0','bouquets'=>[10],'fingerprint'=>str_repeat('7',64)],['id'=>72,'name'=>'TEST global 48 hours','duration'=>48,'period'=>'hours','max_connections'=>2,'credits'=>'1','bouquets'=>[10],'fingerprint'=>str_repeat('8',64)]];
        $c=new ControlCenter\Config($config->root,array_replace($config->values,['trial_worker'=>['shared_secret'=>str_repeat('c',64)],'trial_public_signup_enabled'=>true,'trial_channel'=>'testing','trial_reseller_daily_limit'=>1,'trial_pilot_brand_id'=>$ownerBrand['id'],'trial_owner_unlimited_brand_id'=>$ownerBrand['id']]));
        $worker=new ControlCenter\TrialWorker($c,function($path,$body)use(&$catalogCalls,&$provisions,&$plans):string {$s=json_decode($body,true);if($path==='/branded-trials/plans'){$catalogCalls++;$available=$s['reseller_id']==='88002002'?[$plans[1]]:$plans;return json_encode(['reseller_id'=>$s['reseller_id'],'plans'=>$available]);}$provisions++;throw new RuntimeException('Settings must never provision accounts');});
        $secret=new ControlCenter\Secrets($c);$policies=new ControlCenter\TrialPolicies($app->db,$app->management,$app->auth,$worker);$artifacts=new ControlCenter\BrandArtifacts($app->db,$secret,$c);$offers=new ControlCenter\TrialOffers($app->db,$c,$app->management,$app->auth,$secret,$policies,$artifacts);$service=new ControlCenter\TrialSelfService($app->db,$app->management,$app->auth,$policies,$offers);
        // Model a real0.20 legacy owner approval; migration must not invalidate it.
        $app->db->query('UPDATE trial_plan_grants SET live_enabled=0 WHERE tenant_id=?',[$ownerBrand['tenant_id']]);$app->db->query('UPDATE trial_reseller_defaults SET global_opt_in=0 WHERE tenant_id=?',[$ownerBrand['tenant_id']]);$policies->refresh($owner,['tenant_id'=>$ownerBrand['tenant_id']]);$state=$offers->managerState($owner,['tenant_id'=>$ownerBrand['tenant_id']]);$offers->publish($owner,['tenant_id'=>$ownerBrand['tenant_id'],'expected_revision'=>(int)$state['publication']['revision'],'enabled'=>true,'confirmed_public_mode'=>true]);$before=$offers->publicInfo($ownerBrand['id']);same(true,$before['available']);
        $history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$app->db->query('UPDATE trial_global_packages SET enabled=1,allowed_plans=?,updated_by=? WHERE id=1',[json_encode([17=>$plans[0]['fingerprint']]),$owner['id']]);same($before,$offers->publicInfo($ownerBrand['id']));same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same(0,$provisions);
        foreach(['a','b'] as $which){$t=$app->management->createReseller($owner,['company'=>'TEST global '.$which,'name'=>'TEST global '.$which,'email'=>'global-'.$which.'@example.test','password'=>$password]);$panel=$which==='a'?'88002001':'88002002';$app->db->query('INSERT INTO panel_resellers (panel_id,tenant_id,username,linked_by) VALUES (?,?,?,?)',[$panel,$t['id'],'TEST-global-'.$which,$owner['id']]);$actor=$app->db->one('SELECT id,role,tenant_id FROM users WHERE tenant_id=?',[$t['id']]);$asset=$app->appBrands->upload($actor,['image'=>'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jSuoAAAAASUVORK5CYII=']);$brand=$app->appBrands->save($actor,['name'=>'TEST Global '.$which,'loading_asset'=>$asset['id'],'logo_asset'=>$asset['id'],'icon_asset'=>$asset['id']]);if($which==='a'){$a=$actor;$ta=$t;$ba=$brand;}else{$b=$actor;$tb=$t;$bb=$brand;}}
    };
    $tests['admin approves packages once globally, without choosing any reseller switch or daily limit']=function()use($app,$owner,&$service,&$offers,&$a,&$b,&$plans,&$provisions,&$ownerBrand):void {
        $before=$offers->publicInfo($ownerBrand['id']);$global=$service->packages($owner);$fp=array_column($plans,'fingerprint','id');$saved=$service->savePackages($owner,['expected_revision'=>$global['revision'],'allowed_plan_ids'=>[17,71,72],'plan_fingerprints'=>$fp]);same([17,71,72],$saved['allowed_plan_ids']);same($before,$offers->publicInfo($ownerBrand['id']));same([17,71,72],array_column($service->status($a,[])['plans'],'id'));same([71],array_column($service->status($b,[])['plans'],'id'));same(false,$service->status($a,[])['settings']['enabled']);same(0,$provisions);
        problem(403,fn()=> $service->savePackages($a,['expected_revision'=>$saved['revision'],'allowed_plan_ids'=>[71],'plan_fingerprints'=>$fp]));problem(422,fn()=> $service->savePackages($owner,['expected_revision'=>$saved['revision'],'allowed_plan_ids'=>[71],'plan_fingerprints'=>$fp,'daily_limit'=>1]));
    };
    $register=function(array $brand)use($app,$owner,&$artifacts):void {$id=ControlCenter\Database::id();$revision=(int)$brand['version'];$app->db->query('INSERT INTO app_brand_builds (id,brand_id,brand_version,app_version,manifest,requested_by,build_channel) VALUES (?,?,?,?,?,?,?)',[$id,$brand['id'],$revision,'2.0.122',json_encode(['app_version'=>'2.0.122','app_version_code'=>438]),$owner['id'],'testing']);$artifacts->recordVerified($id,['channel'=>'testing','package_name'=>$brand['package_name'].'.test','version_name'=>'2.0.122.'.$revision.'-test','version_code'=>43800000+$revision,'trial_protocol'=>1,'signer_sha256'=>'3273d0b0294a689565ab4b0c8ef7e1887e2ca680240718f5521628b5c46328b7','apk_sha256'=>str_repeat('a',64),'artifact_url'=>'https://github.com/derangedchief-crypto/ARVIO/releases/download/brand-'.$brand['id'].'-testing/Brand-synthetic.apk']);};
    $input=function(array $actor,int $limit,bool $enabled=true,int $plan=71)use(&$service,&$plans):array {$s=$service->status($actor,[]);$p=array_column($plans,null,'id')[$plan];return ['expected_offer_revision'=>$s['settings']['offer_revision'],'expected_default_revision'=>$s['settings']['default_revision'],'enabled'=>$enabled,'plan_id'=>$plan,'plan_fingerprint'=>$p['fingerprint'],'daily_limit'=>$limit,'confirmed_public_mode'=>$enabled];};
    $tests['verified resellers enable themselves and choose independent quotas without any admin grant row']=function()use($app,$owner,$register,$input,&$service,&$offers,&$a,&$b,&$ta,&$tb,&$ba,&$bb,&$provisions):void {
        $register($ba);$register($bb);$history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');same(null,$app->db->one('SELECT * FROM trial_plan_grants WHERE tenant_id=?',[$ta['id']]));
        $one=$service->saveApp($a,$input($a,100));same(true,$one['active']);same(100,$one['settings']['daily_limit']);same(100,$offers->admitted($ba['id'])['daily_limit']);same(null,$app->db->one('SELECT * FROM trial_plan_grants WHERE tenant_id=?',[$ta['id']]));
        // Stale old per-reseller denial/cap must not survive the corrected model.
        $app->db->query('INSERT INTO trial_plan_grants (tenant_id,enabled,allowed_plans,updated_by,live_enabled,daily_cap,setup_revision) VALUES (?,0,?, ?,0,1,3)',[$tb['id'],'{}',$owner['id']]);$two=$service->saveApp($b,$input($b,7));same(true,$two['active']);same(7,$offers->admitted($bb['id'])['daily_limit']);same(100,$offers->admitted($ba['id'])['daily_limit']);
        problem(409,fn()=> $service->saveApp($b,$input($b,7,true,72)));problem(404,fn()=> $service->saveApp($a,array_replace($input($a,100),['tenant_id'=>$tb['id']])));problem(403,fn()=> $service->saveApp($owner,array_replace($input($a,100),['tenant_id'=>$ta['id']])));same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));same(0,$provisions);
    };
    $tests['resellers can change daily limits themselves; global pause preserves settings and each opt-out']=function()use($owner,$input,&$service,&$offers,&$a,&$b,&$ba,&$bb):void {
        $revision=$offers->publicInfo($ba['id'])['offer_revision'];$stale=$input($a,100);$changed=$service->saveApp($a,$input($a,250));same(250,$changed['settings']['daily_limit']);same(250,$offers->admitted($ba['id'])['daily_limit']);same($revision,$offers->publicInfo($ba['id'])['offer_revision']);problem(409,fn()=> $service->saveApp($a,$stale));
        problem(422,fn()=> $service->saveApp($a,$input($a,0)));problem(422,fn()=> $service->saveApp($a,$input($a,1001)));$state=$offers->globalSettings($owner);$offers->setGlobal($owner,['enabled'=>false,'expected_revision'=>$state['revision']]);same(false,$offers->publicInfo($ba['id'])['available']);same(true,$service->status($a,[])['settings']['enabled']);
        $state=$service->status($a,[]);$service->saveApp($a,['expected_offer_revision'=>$state['settings']['offer_revision'],'enabled'=>false,'daily_limit'=>'unfinished']);$state=$offers->globalSettings($owner);$offers->setGlobal($owner,['enabled'=>true,'expected_revision'=>$state['revision']]);same(false,$offers->publicInfo($ba['id'])['available']);same(true,$offers->publicInfo($bb['id'])['available']);same(250,$service->status($a,[])['settings']['daily_limit']);
    };
    $tests['global package changes require review and apply across resellers without resetting trial history']=function()use($app,$owner,&$service,&$offers,&$a,&$b,&$ba,&$bb,&$plans,&$ownerBrand):void {
        $history=$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id');$before=$offers->publicInfo($ownerBrand['id']);$global=$service->packages($owner);$fp=array_column($plans,'fingerprint','id');$service->savePackages($owner,['expected_revision'=>$global['revision'],'allowed_plan_ids'=>[17,72],'plan_fingerprints'=>$fp]);same(false,$offers->publicInfo($bb['id'])['available']);same([17,72],array_column($service->status($a,[])['plans'],'id'));same([],$service->status($b,[])['plans']);same($before,$offers->publicInfo($ownerBrand['id']));same($history,$app->db->all('SELECT * FROM trial_signup_operations ORDER BY id'));
        problem(409,fn()=> $service->savePackages($owner,['expected_revision'=>$global['revision'],'allowed_plan_ids'=>[17,71],'plan_fingerprints'=>$fp]));$current=$service->packages($owner);problem(409,fn()=> $service->savePackages($owner,['expected_revision'=>$current['revision'],'allowed_plan_ids'=>[71],'plan_fingerprints'=>[71=>str_repeat('f',64)]]));
    };
    $tests['global self-service HTTP contracts expose no per-reseller admin enable or quota controls']=function()use($app,$owner,$http,$password,&$ta,&$tb):void {
        $s=$app->auth->login(['email'=>'global-a@example.test','password'=>$password],'127.0.0.253');$h=['Cookie'=>'control_session='.$s['token'],'X-CSRF-Token'=>$s['csrf']];$o=$app->auth->login(['email'=>$owner['email'],'password'=>$password],'127.0.0.254');$oh=['Cookie'=>'control_session='.$o['token'],'X-CSRF-Token'=>$o['csrf']];
        same(403,$http->request('GET','/api/trial-setup/packages',null,$h,'global-packages-read')['status']);same(403,$http->request('POST','/api/trial-setup/packages',['expected_revision'=>0],$h,'global-packages-write')['status']);same(403,$http->request('POST','/api/trial-setup/app',['enabled'=>false],['Cookie'=>$h['Cookie']],'global-app-csrf')['status']);same(404,$http->request('GET','/api/trial-setup?tenant_id='.$tb['id'],null,$h,'global-app-scope')['status']);
        same(410,$http->request('POST','/api/trial-setup/admin',['allowed'=>true,'daily_limit'=>1],$oh,'global-no-admin-enable')['status']);same(410,$http->request('POST','/api/trial-policy/default',[],$h,'global-no-default-step')['status']);same(410,$http->request('POST','/api/trial-offer-publication',[],$h,'global-no-publish-step')['status']);
    };
}
